"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def HAS_CYCLE(head):
    tortoise = head
    hare = head
    while (((tortoise is not None) and (hare is not None)) and (hare.next is not None)):
        tortoise = tortoise.next
        hare = hare.next.next
        if (tortoise == hare):
            return True
    return False
class Node:
    def __init__(self, value):
        self.value = value
        self.next = None

# Build: 1 → 2 → 3 → None
a = Node(1)
b = Node(2)
c = Node(3)
a.next = b
b.next = c

print(HAS_CYCLE(a))   # Expected: False

# Build: 1 → 2 → 3 → 4 → back to 2
a = Node(1)
b = Node(2)
c = Node(3)
d = Node(4)

a.next = b
b.next = c
c.next = d
d.next = b   # cycle here

print(HAS_CYCLE(a))   # Expected: True
